IDIOMAS = ('pt', 'en', 'es', 'ru')


def ui_para(idioma):
    i = IDIOMAS.index(idioma)

    def resolver(d):
        return {k: (resolver(v) if isinstance(v, dict) else v[i]) for k, v in d.items()}
    return resolver(UI)
